#include <stdlib.h>
#include <string.h>
#include <omp.h>
#include <immintrin.h>

#ifdef __AVX512F__
#define MR 8
#define NR 32
#define KCMAX 192
#define MC 96
#define PPCMAX 16
#define PPCMIN 2
#else
#define MR 6
#define NR 16
#define KCMAX 384
#define MC 96
#define PPCMAX 32
#define PPCMIN 4
#endif

#ifdef __AVX512F__
/* A is read directly from row-major storage (no packing); B is packed. */
static inline void kernel(int kc, const float *restrict a, int lda,
                          const float *restrict b, float *restrict C, int ldc,
                          int mr, int nr, int first)
{
    const float *a0 = a;
    const float *a1 = a + (size_t)(1 < mr ? 1 : mr - 1) * lda;
    const float *a2 = a + (size_t)(2 < mr ? 2 : mr - 1) * lda;
    const float *a3 = a + (size_t)(3 < mr ? 3 : mr - 1) * lda;
    const float *a4 = a + (size_t)(4 < mr ? 4 : mr - 1) * lda;
    const float *a5 = a + (size_t)(5 < mr ? 5 : mr - 1) * lda;
    const float *a6 = a + (size_t)(6 < mr ? 6 : mr - 1) * lda;
    const float *a7 = a + (size_t)(7 < mr ? 7 : mr - 1) * lda;

#define DECL(i) __m512 c##i##0 = _mm512_setzero_ps(), c##i##1 = _mm512_setzero_ps();
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5) DECL(6) DECL(7)
#undef DECL

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_load_ps(b);
        __m512 b1 = _mm512_load_ps(b + 16);
        __m512 x;
#define FM(i) x = _mm512_set1_ps(a##i[k]); \
        c##i##0 = _mm512_fmadd_ps(x, b0, c##i##0); \
        c##i##1 = _mm512_fmadd_ps(x, b1, c##i##1);
        FM(0) FM(1) FM(2) FM(3) FM(4) FM(5) FM(6) FM(7)
#undef FM
        b += NR;
    }

    if (mr == MR && nr == NR) {
        if (first) {
#define ST(i) _mm512_storeu_ps(C + (size_t)(i) * ldc, c##i##0); \
              _mm512_storeu_ps(C + (size_t)(i) * ldc + 16, c##i##1);
            ST(0) ST(1) ST(2) ST(3) ST(4) ST(5) ST(6) ST(7)
#undef ST
        } else {
#define ST(i) { float *p = C + (size_t)(i) * ldc; \
              _mm512_storeu_ps(p, _mm512_add_ps(_mm512_loadu_ps(p), c##i##0)); \
              _mm512_storeu_ps(p + 16, _mm512_add_ps(_mm512_loadu_ps(p + 16), c##i##1)); }
            ST(0) ST(1) ST(2) ST(3) ST(4) ST(5) ST(6) ST(7)
#undef ST
        }
    } else {
        __mmask16 m0 = nr >= 16 ? (__mmask16)0xFFFF : (__mmask16)((1u << nr) - 1);
        __mmask16 m1 = nr >= 32 ? (__mmask16)0xFFFF
                     : nr > 16 ? (__mmask16)((1u << (nr - 16)) - 1) : (__mmask16)0;
#define ST(i) if ((i) < mr) { float *p = C + (size_t)(i) * ldc; \
            if (first) { \
                _mm512_mask_storeu_ps(p, m0, c##i##0); \
                _mm512_mask_storeu_ps(p + 16, m1, c##i##1); \
            } else { \
                _mm512_mask_storeu_ps(p, m0, _mm512_add_ps(_mm512_maskz_loadu_ps(m0, p), c##i##0)); \
                _mm512_mask_storeu_ps(p + 16, m1, _mm512_add_ps(_mm512_maskz_loadu_ps(m1, p + 16), c##i##1)); \
            } }
        ST(0) ST(1) ST(2) ST(3) ST(4) ST(5) ST(6) ST(7)
#undef ST
    }
}
#else
typedef float v8 __attribute__((vector_size(32)));
typedef float v8u __attribute__((vector_size(32), aligned(4)));

/* A is read directly from row-major storage (no packing); B is packed. */
static inline void kernel(int kc, const float *restrict a, int lda,
                          const float *restrict b, float *restrict C, int ldc,
                          int mr, int nr, int first)
{
    const float *a0 = a;
    const float *a1 = a + (size_t)(1 < mr ? 1 : mr - 1) * lda;
    const float *a2 = a + (size_t)(2 < mr ? 2 : mr - 1) * lda;
    const float *a3 = a + (size_t)(3 < mr ? 3 : mr - 1) * lda;
    const float *a4 = a + (size_t)(4 < mr ? 4 : mr - 1) * lda;
    const float *a5 = a + (size_t)(5 < mr ? 5 : mr - 1) * lda;

    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        float x;
        x = a0[k]; c00 += x * b0; c01 += x * b1;
        x = a1[k]; c10 += x * b0; c11 += x * b1;
        x = a2[k]; c20 += x * b0; c21 += x * b1;
        x = a3[k]; c30 += x * b0; c31 += x * b1;
        x = a4[k]; c40 += x * b0; c41 += x * b1;
        x = a5[k]; c50 += x * b0; c51 += x * b1;
        b += NR;
    }

    if (mr == MR && nr == NR) {
        if (first) {
#define ST(r, x0, x1) do { \
            *(v8u *)(C + (size_t)(r) * ldc) = x0; \
            *(v8u *)(C + (size_t)(r) * ldc + 8) = x1; \
        } while (0)
            ST(0, c00, c01); ST(1, c10, c11); ST(2, c20, c21);
            ST(3, c30, c31); ST(4, c40, c41); ST(5, c50, c51);
#undef ST
        } else {
#define ST(r, x0, x1) do { \
            *(v8u *)(C + (size_t)(r) * ldc) += x0; \
            *(v8u *)(C + (size_t)(r) * ldc + 8) += x1; \
        } while (0)
            ST(0, c00, c01); ST(1, c10, c11); ST(2, c20, c21);
            ST(3, c30, c31); ST(4, c40, c41); ST(5, c50, c51);
#undef ST
        }
    } else {
        v8 t[MR][2] __attribute__((aligned(32)));
        t[0][0] = c00; t[0][1] = c01; t[1][0] = c10; t[1][1] = c11;
        t[2][0] = c20; t[2][1] = c21; t[3][0] = c30; t[3][1] = c31;
        t[4][0] = c40; t[4][1] = c41; t[5][0] = c50; t[5][1] = c51;
        int n0 = nr < 8 ? nr : 8;
        int n1 = nr > 8 ? nr - 8 : 0;
        __m256i idx = _mm256_setr_epi32(0, 1, 2, 3, 4, 5, 6, 7);
        __m256i m0 = _mm256_cmpgt_epi32(_mm256_set1_epi32(n0), idx);
        __m256i m1 = _mm256_cmpgt_epi32(_mm256_set1_epi32(n1), idx);
        for (int i = 0; i < mr; i++) {
            float *cr = C + (size_t)i * ldc;
            __m256 v0 = _mm256_load_ps((const float *)&t[i][0]);
            __m256 v1 = _mm256_load_ps((const float *)&t[i][1]);
            if (!first) {
                v0 = _mm256_add_ps(v0, _mm256_maskload_ps(cr, m0));
                if (n1) v1 = _mm256_add_ps(v1, _mm256_maskload_ps(cr + 8, m1));
            }
            _mm256_maskstore_ps(cr, m0, v0);
            if (n1) _mm256_maskstore_ps(cr + 8, m1, v1);
        }
    }
}
#endif

static float *gB;
static size_t capB;

static float *grow(float **p, size_t *cap, size_t nfloats)
{
    size_t bytes = (nfloats * sizeof(float) + 63) & ~(size_t)63;
    if (bytes > *cap) {
        free(*p);
        *p = (float *)aligned_alloc(64, bytes);
        *cap = bytes;
    }
    return *p;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int nkb = (n + KCMAX - 1) / KCMAX;
    int kcb = (n + nkb - 1) / nkb;
    kcb = (kcb + 7) & ~7;
    nkb = (n + kcb - 1) / kcb;

    int npB = (n + NR - 1) / NR;
    float *Bp = grow(&gB, &capB, (size_t)npB * NR * n);

    int nth = omp_get_max_threads();
    int nib = (n + MC - 1) / MC;
    int njb = (4 * nth + nib - 1) / nib;
    if (njb < 1) njb = 1;
    int ppc = (npB + njb - 1) / njb;
    if (ppc > PPCMAX) ppc = PPCMAX;
    if (ppc < PPCMIN) ppc = PPCMIN;
    if (ppc > npB) ppc = npB;
    njb = (npB + ppc - 1) / ppc;
    int ntasks = nib * njb;

    #pragma omp parallel
    {
        #pragma omp for collapse(2) schedule(static)
        for (int kb = 0; kb < nkb; kb++) {
            for (int jp = 0; jp < npB; jp++) {
                int p0 = kb * kcb;
                int kc = n - p0 < kcb ? n - p0 : kcb;
                int j0 = jp * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                float *dst = Bp + (size_t)p0 * npB * NR + (size_t)jp * kc * NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(p0 + k) * n + j0;
                    float *d = dst + (size_t)k * NR;
                    if (nr == NR) {
                        memcpy(d, src, NR * sizeof(float));
                    } else {
                        int j = 0;
                        for (; j < nr; j++) d[j] = src[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }
        }

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntasks; t++) {
            int ib = t / njb, jb = t % njb;
            int i0 = ib * MC;
            int mc = n - i0 < MC ? n - i0 : MC;
            int jp0 = jb * ppc;
            int jp1 = jp0 + ppc < npB ? jp0 + ppc : npB;
            for (int kb = 0; kb < nkb; kb++) {
                int p0 = kb * kcb;
                int kc = n - p0 < kcb ? n - p0 : kcb;
                const float *bbase = Bp + (size_t)p0 * npB * NR;
                const float *abase = A + (size_t)i0 * n + p0;
                for (int jp = jp0; jp < jp1; jp++) {
                    int jj = jp * NR;
                    int nr = n - jj < NR ? n - jj : NR;
                    const float *bp = bbase + (size_t)jp * kc * NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, abase + (size_t)ir * n, n, bp,
                               C + (size_t)(i0 + ir) * n + jj, n,
                               mr, nr, kb == 0);
                    }
                }
            }
        }
    }
}
